const e=$input.first().json||{};
const wf=e.workflow||{};
const ex=e.execution||e.trigger||{};
const err=ex.error||e.error||{};
const name=String(wf.name||'an unknown workflow');
const nodeName=(err.node&&err.node.name)?String(err.node.name):String(ex.lastNodeExecuted||'an unidentified node');
const msg=String(err.message||'No error message was reported.');
const url=String(ex.url||'');
const execId=String(ex.id||'');
const stageKey=(function(){const after=String(name).replace(/^[\s\S]*?GTM/i,'');const m=/(\d{1,2}A?)/i.exec(after);return m?m[1].toUpperCase():'';})();
const stages={'00':'setup and seeding','01':'booth scan intake','02':'HubSpot sync','02A':'pre-write CRM lookup','03':'Slack delivery','04':'company enrichment','05':'AI synthesis','06':'Slack action handling','07':'the task test harness','99':'the failure handler itself'};
const impacts={'00':'Only setup and seeding broke. No booth scan is affected, but the policy, Data Tables, HubSpot properties or Slack channels may be half-provisioned - rerun this workflow, which is safe to repeat.','01':'A booth scan may not have been recorded at all. Re-send the same webhook payload: the ledger row is only marked complete at the end, so replaying an incomplete scan is safe.','02':'The lead was classified and the booth may already have been alerted, but HubSpot is likely out of date. Look the contact up by email and check the tier and booth conversation.','02A':'No CRM state was changed, but downstream synthesis and the Slack card lost owner, relationship and open-deal context. The tier itself is unaffected.','03':'HubSpot is up to date but nobody was notified. Tell the booth manually, and treat this as urgent while the event is live.','04':'Classification, CRM and the alert still ran. Only the company intel is missing, so the alert went out with less context and possibly without a verified headcount.','05':'Deterministic rules still decided the tier. The alert fell back to a grounded generic opening question instead of a synthesised one.','06':'A rep pressed a button and it did not take effect. The underlying lead data is unchanged, so ask them to try again.','07':'Only the test run broke. No production booth scan is affected.','99':'The failure handler itself failed, so another failure may have gone unreported. Check the execution list for errors around this time.'};
const stage=stages[stageKey]||'an Oak GTM stage';
const impact=impacts[stageKey]||'Check the execution to see which side effects completed before the failure.';
const hint=/401|403|unauthoriz|authenticat|credential/i.test(msg)?'This reads like a credential problem. Verify the token has not expired and still carries the required scopes.':/429|rate limit/i.test(msg)?'This reads like rate limiting. It should clear on its own; retry the execution once traffic settles.':/timeout|ETIMEDOUT|ECONNRESET|ENOTFOUND/i.test(msg)?'This reads like a network or timeout problem with an external service rather than a logic bug.':/property|does not exist|invalid/i.test(msg)?'This reads like a schema mismatch. Confirm the expected custom properties and Data Table columns exist, and rerun workflow 00.':'';
const trunc=(t,n)=>{const x=String(t==null?'':t);return x.length>n?x.slice(0,n-3)+'...':x;};
const lines=[':rotating_light: *Oak GTM failure - '+stage+'*','*Workflow:* '+name,'*Failed at:* '+nodeName,'*Error:* '+trunc(msg,600),'','*What this means:* '+impact];
if(hint)lines.push('*Likely cause:* '+hint);
if(url)lines.push('','<'+url+'|Open the failed execution>');
else if(execId)lines.push('','Execution id: '+execId);
return[{json:{text:trunc(lines.join('\n'),3500),workflow_name:name,workflow_id:String(wf.id||''),failed_node:nodeName,error_message:msg,execution_id:execId,execution_url:url,stage,likely_cause:hint||null,reported_at:new Date().toISOString()}}];
